package dev.eugheist.ttmodern;
final class AdvancedToolModesAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT advanced modes: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){for(String type:new String[]{"pick","shovel","axe"}){check(AdvancedToolMining.material(net.minecraft.world.level.block.Blocks.OAK_LOG.defaultBlockState(),type),"original tool-not-required wood accepted "+type);check(AdvancedToolMining.material(net.minecraft.world.level.block.Blocks.GLASS.defaultBlockState(),type),"original tool-not-required glass accepted "+type);check(AdvancedToolMining.material(net.minecraft.world.level.block.Blocks.SNOW_BLOCK.defaultBlockState(),type)==type.equals("shovel"),"original required snow material "+type);check(AdvancedToolMining.material(net.minecraft.world.level.block.Blocks.STONE.defaultBlockState(),type)==type.equals("pick"),"original required rock material "+type);}var stack=new net.minecraft.world.item.ItemStack(KamiTools.PICK.get());net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,stack,t->t.putString("Unrelated","keep"));check(AdvancedToolModes.get(stack)==0,"default single");for(int expected:new int[]{1,2,0})check(AdvancedToolModes.change(stack)==expected,"three mode cycle");check(stack.get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag().getString("Unrelated").equals("keep"),"unrelated data retained");AdvancedToolModes.change(stack);var encoded=stack.save(server.registryAccess());var decoded=net.minecraft.world.item.ItemStack.parseOptional(server.registryAccess(),(net.minecraft.nbt.CompoundTag)encoded);check(AdvancedToolModes.get(decoded)==1,"mode persistence");var origin=new net.minecraft.core.BlockPos(-19,-5,27);var column=AdvancedToolModes.shovel(2,net.minecraft.core.Direction.UP).positions(origin);check(column.size()==15&&column.contains(origin.below(8))&&column.contains(origin.above(7))&&!column.contains(origin.above(8)),"original shovel vertical exclusive column");for(var face:net.minecraft.core.Direction.values()){check(AdvancedToolModes.pick(0,face).positions(origin).isEmpty(),"single leaves center to vanilla");var area=AdvancedToolModes.pick(1,face).positions(origin);check(area.size()==24&&new java.util.HashSet<>(area).size()==24&&!area.contains(origin),"original plane count excludes center "+face);for(var pos:area){var d=pos.subtract(origin);check(d.getX()*face.getStepX()+d.getY()*face.getStepY()+d.getZ()*face.getStepZ()==0,"plane normal "+face);if(face.getAxis()!=net.minecraft.core.Direction.Axis.Y)check(d.getY()>=-1&&d.getY()<=3,"original asymmetric vertical range");}var tunnel=AdvancedToolModes.pick(2,face).positions(origin);check(tunnel.size()==(face.getAxisDirection()==net.minecraft.core.Direction.AxisDirection.POSITIVE?10:9),"original exclusive directional tunnel length "+face);for(var pos:tunnel){var d=pos.subtract(origin);check(d.getX()*face.getStepX()+d.getY()*face.getStepY()+d.getZ()*face.getStepZ()<0,"tunnel extends behind struck face "+face);}}
 System.out.println("TT ADVANCED TOOL MODES AUDIT: ALL PASS (NBT cycle/persistence,all six faces,exact asymmetric 5x5 and directional exclusive tunnel bounds,center excluded)");}
}
